mapper.sql:
SELECT ROW_NUMBER() OVER(ORDER BY TO_DATE(A.REG_DTTM, 'YYYYMMDDHH24MISS') DESC) AS "LINE_NO" /* Row Number */ , D.ORGNM AS "ORGNM" /* 기관 I */ , B.ORG_ID AS "ORG_ID" /* 기관 I ID (HIDDEN) */ , C.DEPTNM AS "DEPTNM" /* 학과 I */ , B.DEPT_ID AS "DEPT_ID" /* 학과 I ID (HIDDEN) */ , SMSTR.SMSTR_CHRT_ID /* 학기/기수 ID */ , SMSTR.DGRS_YR /* 학위연도 */ , SMSTR.DGRS_SMSTR_CHRT /* 학기/기수 */ , SBJ.SBJCTNM || ' (' || SBJ.DVCLAS_NO || '반)' AS SBJCTNM , TO_CHAR(TO_DATE(A.REG_DTTM, 'YYYYMMDDHH24MISS'), 'YYYY.MM.DD HH24:MI') AS "REG_DTTM" /* 일시 */ , B.STDNT_NO AS "STDNT_NO" /* 학번/사번 */ , B.USERNM AS "USERNM" /* 등록자 명 */ , A.RGTR_ID AS "RGTR_ID" /* 등록자 ID (HIDDEN) */ , A.SYS_ERR_PAGENM AS "SYS_ERR_PAGENM" /* 오류페이지 */ , A.SYS_ERR_MSG_ID AS "SYS_ERR_MSG_ID" /* 에러메시지 ID (HIDDEN) */ FROM TB_LMS_SYS_ERR_MSG A JOIN TB_LMS_USER B ON A.RGTR_ID = B.USER_ID JOIN TB_LMS_DEPT C ON B.DEPT_ID = C.DEPT_ID JOIN TB_LMS_ORG D ON B.ORG_ID = D.ORG_ID JOIN TB_LMS_SBJCT SBJ ON A.SBJCT_ID = SBJ.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SMSTR ON SBJ.SMSTR_CHRT_ID = SMSTR.SMSTR_CHRT_ID WHERE 1=1
AND B.ORG_ID = #{orgId}
AND B.DEPT_ID = #{deptId}
AND B.STDNT_NO = #{stdntNo}
AND SMSTR.DGRS_YR = #{dgrsYr}
AND SMSTR.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}
AND B.USERNM LIKE '%' || #{usernm} || '%'
AND #{searchFrom} < A.REG_DTTM
AND A.REG_DTTM < #{searchTo}
AND (B.USERNM LIKE '%'||#{searchValue}||'%' OR SBJ.SBJCTNM LIKE '%'||#{searchValue}||'%' )

SELECT SE.* , ROW_NUMBER() OVER(ORDER BY TO_DATE(SE.REG_DTTM, 'YYYYMMDDHH24MISS') DESC) AS "LINE_NO" /* Row Number */ , O.ORGNM , O.ORG_ID , D.DEPTNM , U.DEPT_ID , SMSTR.SMSTR_CHRT_ID , SMSTR.DGRS_YR , SMSTR.DGRS_SMSTR_CHRT , CASE WHEN S.SBJCTNM IS NOT NULL THEN S.SBJCTNM || ' (' || S.DVCLAS_NO || '반)' END AS SBJCTNM , STD.STDNT_NO , U.USERNM FROM TB_LMS_SYS_ERR SE JOIN TB_LMS_USER U ON SE.RGTR_ID = U.USER_ID LEFT JOIN TB_LMS_SBJCT S ON SE.SBJCT_ID = S.SBJCT_ID LEFT JOIN TB_LMS_DEPT D ON S.DEPT_ID = D.DEPT_ID LEFT JOIN TB_LMS_SMSTR_CHRT SMSTR ON S.SMSTR_CHRT_ID = SMSTR.SMSTR_CHRT_ID LEFT JOIN TB_LMS_ORG O ON SMSTR.ORG_ID = O.ORG_ID -- 학생 LEFT JOIN TB_LMS_ATNDLC STD ON U.USER_ID = STD.USER_ID AND S.SBJCT_ID = STD.SBJCT_ID -- 교사 LEFT JOIN TB_LMS_SBJCT_ADM PROF ON U.USER_ID = PROF.USER_ID AND S.SBJCT_ID = PROF.SBJCT_ID WHERE 1 = 1
AND O.ORG_ID = #{orgId}
AND S.DEPT_ID = #{deptId}
AND STD.STDNT_NO LIKE '%'|| #{stdntNo} ||'%'
AND SMSTR.DGRS_YR = #{dgrsYr}
AND SMSTR.DGRS_SMSTR_CHRT = #{dgrsSmstrChrt}
AND U.USERNM LIKE '%' || #{usernm} || '%'
AND #{searchFrom} < SE.REG_DTTM
AND SE.REG_DTTM < #{searchTo}
AND ( U.USERNM LIKE '%'||#{searchValue}||'%' OR S.SBJCTNM LIKE '%'||#{searchValue}||'%' )

mapper.select:
/*	설명 : 시스템 오류현황 상세 조회	*/
SELECT	*
FROM	TB_LMS_SYS_ERR SE
WHERE	1 = 1
		AND 	SE.SYS_ERR_ID = #{sysErrId}
